{
  "title": "Discussion on tax filing, domain purchase, and app viability",
  "topics": [
    {
      "id": "tax-filing",
      "title": "Tax filing complications and costs",
      "claims": [
        {
          "text": "Paying 500 UAH to a contact (Sveta) helped avoid larger penalties from incorrectly marked columns in declarations",
          "evidence": [1]
        },
        {
          "text": "The inspector had not reviewed declarations for 1.5 years and was later disciplined, leading to a thorough re‑check of all years' declarations",
          "evidence": [1]
        },
        {
          "text": "Correct re‑filing cost about 1 000 UAH, which was cheaper than paying all fines",
          "evidence": [1]
        },
        {
          "text": "The main difficulty is not calculating taxes themselves but ensuring each column is correctly matched and subtracted",
          "evidence": [8]
        },
        {
          "text": "The whole procedure typically takes about an hour with Excel, possibly one day maximum",
          "evidence": [5]
        },
        {
          "text": "Quarterly reports must be submitted and taxes paid correctly",
          "evidence": [7]
        }
      ]
    },
    {
      "id": "domain-purchase",
      "title": "Domain acquisition discussion",
      "claims": [
        {
          "text": "User P2 has not bought a domain yet",
          "evidence": [2]
        },
        {
          "text": "P1 sarcastically suggests someone buying a calculator will have money for a domain",
          "evidence": [4]
        },
        {
          "text": "P4 doubts anyone will buy the domain, calling it a useless item",
          "evidence": [9]
        },
        {
          "text": "P4 later describes the domain as a “silly thing” that won’t evaporate even in heat",
          "evidence": [10]
        }
      ]
    },
    {
      "id": "app-profitability",
      "title": "Viability of a web/app product",
      "claims": [
        {
          "text": "Web platforms are the easiest to build but less profitable than Android/iOS apps",
          "evidence": [11]
        },
        {
          "text": "SEO performance is poor; the site does not appear even on the 10th Google page",
          "evidence": [11]
        },
        {
          "text": "No external traffic from social platforms or contextual ads; app stores promote new apps more effectively",
          "evidence": [11]
        },
        {
          "text": "No passive ad revenue from the website and user retention is nearly zero due to early paywalls",
          "evidence": [11]
        },
        {
          "text": "Conversion is presumed near zero because the product does not simplify enough or integrate with banks or tax cabinets",
          "evidence": [11]
        },
        {
          "text": "Successful similar projects use fast delivery (< 1 week) and cross‑platform stacks like Flutter, copying popular ideas with minor tweaks",
          "evidence": [12]
        },
        {
          "text": "P1 doubts the market will buy such a product, betting it won’t sell in months",
          "evidence": [17]
        }
      ]
    },
    {
      "id": "source-code-access",
      "title": "Access to source code / password concerns",
      "claims": [
        {
          "text": "P4 claims the source code is bundled and implies a password is stored locally for a 100 % discount",
          "evidence": [23]
        },
        {
          "text": "P1 asks if the source code password can be found by searching",
          "evidence": [21]
        },
        {
          "text": "P4 responds sarcastically that they didn’t pay 299 UAH for it",
          "evidence": [22]
        },
        {
          "text": "P5 calls P4 a pirate and suggests writing to him for the password",
          "evidence": [24, 25]
        },
        {
          "text": "P4 reacts with frustration and mentions wanting a cold rum",
          "evidence": [26]
        },
        {
          "text": "P1 believes most LinkedIn users could hack the app easily",
          "evidence": [28]
        },
        {
          "text": "P4 describes the app as a “local‑first” app with USD/UAH rates refreshed every 5 minutes, but the paid bundle actually contains the secret code",
          "evidence": [29]
        },
        {
          "text": "P4 labels the project as a “free vibe‑code” experiment with low sense, where knowledgeable people might look for the password and others would just buy or ignore it",
          "evidence": [30]
        }
      ]
    }
  ],
  "decisions": [],
  "openQuestions": [
    {
      "text": "Is there a viable audience of at least ten people willing to pay 299 UAH for the app?",
      "evidence": [20]
    },
    {
      "text": "Can the source code password be discovered through local storage search?",
      "evidence": [21, 23]
    }
  ]
}
